('SO3.2','SO3.2-M3-05','วิเคราะห์ผลเสียจากการว่างงาน และแนวทางแก้ปัญหา','ส ๓.๒ ม.๓/๕',34),
('SO3.2','SO3.2-M3-06','วิเคราะห์สาเหตุ และวิธีการกีดกันทางการค้าในการค้าระหว่างประเทศ','ส ๓.๒ ม.๓/๖',35),
('SO4.1','SO4.1-M3-01','วิเคราะห์เรื่องราวเหตุการณ์สำคัญทางประวัติศาสตร์ได้อย่างมีเหตุผลตามวิธีการทางประวัติศาสตร์','ส ๔.๑ ม.๓/๑',36),
('SO4.1','SO4.1-M3-02','ใช้วิธีการทางประวัติศาสตร์ในการศึกษาเรื่องราวต่าง ๆ ที่ตนสนใจ','ส ๔.๑ ม.๓/๒',37),
('SO4.2','SO4.2-M3-01','อธิบายพัฒนาการทางสังคม เศรษฐกิจและการเมืองของภูมิภาคต่าง ๆ ในโลกโดยสังเขป','ส ๔.๒ ม.๓/๑',38),
('SO4.2','SO4.2-M3-02','วิเคราะห์ผลของการเปลี่ยนแปลงที่นำไปสู่ความร่วมมือและความขัดแย้งในคริสต์ศตวรรษที่ ๒๐ ตลอดจนความพยายามในการขจัดปัญหาความขัดแย้ง','ส ๔.๒ ม.๓/๒',39),
('SO4.3','SO4.3-M3-01','วิเคราะห์พัฒนาการของไทยสมัยรัตนโกสินทร์ในด้านต่าง ๆ','ส ๔.๓ ม.๓/๑',40),
('SO4.3','SO4.3-M3-02','วิเคราะห์ปัจจัยที่ส่งผลต่อความมั่นคงและความเจริญรุ่งเรืองของไทยในสมัยรัตนโกสินทร์','ส ๔.๓ ม.๓/๒',41),
('SO4.3','SO4.3-M3-03','วิเคราะห์ภูมิปัญญาและวัฒนธรรมไทยสมัยรัตนโกสินทร์ และอิทธิพลต่อการพัฒนาชาติไทย','ส ๔.๓ ม.๓/๓',42),
('SO4.3','SO4.3-M3-04','วิเคราะห์บทบาทของไทยในสมัยประชาธิปไตย','ส ๔.๓ ม.๓/๔',43),
('SO5.1','SO5.1-M3-01','วิเคราะห์ลักษณะทางกายภาพของทวีปอเมริกาเหนือ และทวีปอเมริกาใต้ โดยเลือกใช้แผนที่เฉพาะเรื่องและเครื่องมือทางภูมิศาสตร์สืบค้นข้อมูล','ส ๕.๑ ม.๓/๑',44),
('SO5.1','SO5.1-M3-02','วิเคราะห์สาเหตุการเกิดภัยพิบัติและผลกระทบในทวีปอเมริกาเหนือ และทวีปอเมริกาใต้','ส ๕.๑ ม.๓/๒',45),
('SO5.2','SO5.2-M3-01','สำรวจและระบุทำเลที่ตั้งของกิจกรรมทางเศรษฐกิจและสังคมในทวีปอเมริกาเหนือ และทวีปอเมริกาใต้','ส ๕.๒ ม.๓/๑',46),
('SO5.2','SO5.2-M3-02','วิเคราะห์ปัจจัยทางกายภาพและปัจจัยทางสังคมที่ส่งผลต่อทำเลที่ตั้งของกิจกรรมทางเศรษฐกิจและสังคมในทวีปอเมริกาเหนือและทวีปอเมริกาใต้','ส ๕.๒ ม.๓/๒',47),
('SO5.2','SO5.2-M3-03','สืบค้น อภิปรายประเด็นปัญหาจากปฏิสัมพันธ์ระหว่างสิ่งแวดล้อมทางกายภาพกับมนุษย์ที่เกิดขึ้นในทวีปอเมริกาเหนือ และทวีปอเมริกาใต้','ส ๕.๒ ม.๓/๓',48),
('SO5.2','SO5.2-M3-04','วิเคราะห์แนวทางการจัดการภัยพิบัติและการจัดการทรัพยากรและสิ่งแวดล้อมในทวีปอเมริกาเหนือ และทวีปอเมริกาใต้ที่ยั่งยืน','ส ๕.๒ ม.๓/๔',49),
('SO5.2','SO5.2-M3-05','ระบุความร่วมมือระหว่างประเทศที่มีผลต่อการจัดการทรัพยากรและสิ่งแวดล้อม','ส ๕.๒ ม.๓/๕',50)
),
upserted as (
 insert into public.learning_objectives(topic_id,code,name,sequence_no,status)
 select t.id,seed.code,seed.name,seed.seq,'active'
 from seed join public.learning_topics t on t.code=seed.standard_code
 join public.learning_skills sk on sk.id=t.skill_id and sk.code='SOCIAL-STUDIES'
 on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no,updated_at=now()
 returning id,code
)
insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes,indicator_classification)
select u.id,c.id,g.id,seed.seq,false,
 'OBEC source indicator: '||seed.source_code||'. Classification intentionally unset pending exact verification of the 2023 between-learning/terminal columns.',
 null
from seed join upserted u on u.code=seed.code
join public.learning_topics t on t.code=seed.standard_code
join public.learning_skills sk on sk.id=t.skill_id and sk.code='SOCIAL-STUDIES'
join public.learning_curricula c on c.code='TH-BASIC-CORE-2008-2017'
join public.learning_grade_levels g on g.code='M3'
on conflict(objective_id,curriculum_id,grade_level_id) do update
set sequence_no=excluded.sequence_no,notes=excluded.notes,indicator_classification=excluded.indicator_classification,updated_at=now();
